// Not sure we need this file since signer will be used instead of a wallet or privatekey
import { BigNumber, ethers } from 'ethers';
import { CurrentConfig, Environment } from './config.js';
// Single copies of provider and wallet
const mainnetProvider = new ethers.providers.JsonRpcProvider(CurrentConfig.rpc.mainnet);
const wallet = createWallet();
// Interfaces
export var TransactionState;
(function (TransactionState) {
    TransactionState["Failed"] = "Failed";
    TransactionState["New"] = "New";
    TransactionState["Rejected"] = "Rejected";
    TransactionState["Sending"] = "Sending";
    TransactionState["Sent"] = "Sent";
})(TransactionState || (TransactionState = {}));
// Provider and Wallet Functions
export function getMainnetProvider() {
    return mainnetProvider;
}
export function getProvider() {
    return wallet.provider;
}
export function getWalletAddress() {
    return wallet.address;
}
export async function sendTransaction(transaction) {
    if (transaction.value) {
        transaction.value = BigNumber.from(transaction.value);
    }
    console.log('sending transaction via wallet - providers');
    return sendTransactionViaWallet(transaction);
}
// Internal Functionality
function createWallet() {
    let provider = mainnetProvider;
    if (CurrentConfig.env == Environment.LOCAL) {
        provider = new ethers.providers.JsonRpcProvider(CurrentConfig.rpc.local);
    }
    return new ethers.Wallet(CurrentConfig.wallet.privateKey, provider);
}
// Transacting with a wallet extension via a Web3 Provider
async function sendTransactionViaWallet(transaction) {
    console.log('sending transaction via wallet');
    if (transaction.value) {
        transaction.value = BigNumber.from(transaction.value);
    }
    console.log('attempting to send wallet transaction', transaction);
    try {
        const txRes = await wallet.sendTransaction(transaction);
        console.log('Transaction hash:', txRes.hash);
        let receipt = null;
        const provider = getProvider();
        if (!provider) {
            return TransactionState.Failed;
        }
        while (receipt === null) {
            try {
                receipt = await provider.getTransactionReceipt(txRes.hash);
                if (receipt === null) {
                    continue;
                }
            }
            catch (e) {
                console.log(`Receipt error:`, e);
                break;
            }
        }
        // Log detailed transaction receipt
        if (receipt) {
            console.log('Transaction receipt:', {
                status: receipt.status,
                gasUsed: receipt.gasUsed.toString(),
                effectiveGasPrice: receipt.effectiveGasPrice.toString(),
                blockNumber: receipt.blockNumber,
                confirmations: receipt.confirmations
            });
            if (receipt.status === 0) {
                // Transaction failed on-chain
                console.log('Transaction failed on-chain. Attempting to get failure reason...');
                try {
                    const tx = await provider.getTransaction(txRes.hash);
                    const txRequest = {
                        ...tx,
                        type: tx.type || undefined
                    };
                    const code = await provider.call(txRequest, tx.blockNumber);
                    console.log('Transaction revert reason:', code);
                }
                catch (err) {
                    console.log('Error getting revert reason:', err);
                }
                return TransactionState.Failed;
            }
            return TransactionState.Sent;
        }
        else {
            console.log('No receipt received after waiting');
            return TransactionState.Failed;
        }
    }
    catch (e) {
        console.error('Transaction error:', {
            message: e?.message,
            code: e?.code,
            data: e?.data
        });
        return TransactionState.Failed;
    }
}
